import { prisma } from '../lib/prisma.js'
import { ApiError } from '../utils/ApiError.js'
export async function listar(req,res){res.json(await prisma.horarioFuncionamento.findMany({where:{estabelecimentoId:req.estabelecimentoId},orderBy:{diaSemana:'asc'}}))}
export async function atualizarDia(req,res){const diaSemana=Number(req.params.diaSemana);if(!Number.isInteger(diaSemana)||diaSemana<0||diaSemana>6)throw new ApiError(400,'diaSemana inválido.');const {ativo,abre,fecha}=req.body;if(abre!==undefined&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(abre))throw new ApiError(400,'Horário de abertura inválido.');if(fecha!==undefined&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(fecha))throw new ApiError(400,'Horário de fechamento inválido.');if(ativo&&abre&&fecha&&abre>=fecha)throw new ApiError(400,'A abertura deve ser anterior ao fechamento.');const where={estabelecimentoId_diaSemana:{estabelecimentoId:req.estabelecimentoId,diaSemana}};const horario=await prisma.horarioFuncionamento.upsert({where,update:{ativo:Boolean(ativo),abre,fecha},create:{estabelecimentoId:req.estabelecimentoId,diaSemana,ativo:ativo??true,abre:abre??'11:00',fecha:fecha??'23:00'}});res.json(horario)}
